import type { CatalogProduct } from './catalog';

// Every product in the catalog, generated by scripts/build-mobile-catalog.mjs. Loaded when the app starts
// (while the splash screen is up) so categories, search, cart and product pages never wait for products.
// Required rather than imported so TypeScript does not infer a type from the ~20 MB file.
// eslint-disable-next-line @typescript-eslint/no-require-imports
export const bundledCatalogProducts = require('./catalogProducts.json') as CatalogProduct[];
